import { contextBridge, ipcRenderer } from 'electron';

// Type definitions for the exposed API
interface VideoState {
    position: number;
    duration: number;
    paused: boolean;
    volume: number;
    playing: boolean;
}

interface FrameData {
    buffer: ArrayBuffer;
    width: number;
    height: number;
    rotation: number;
    format: 'rgba' | 'yuv420';
}

/** 幀元數據（只在首幀或變化時發送） */
interface FrameMetadata {
    width: number;
    height: number;
    rotation: number;
    format: 'rgba' | 'yuv420';
}

interface VideoEvent {
    type: string;
    instanceId?: string;
    error?: boolean;
    errorCode?: number;
    errorMessage?: string;
    [key: string]: unknown;
}

interface FileSupportResult {
    supported: boolean;
    hasVideo: boolean;
    hasAudio: boolean;
    error: string | null;
    format?: string;
    videoCodec?: string;
    audioCodec?: string;
}

interface AppInfo {
    name: string;
    version: string;
    platform: string;
    arch: string;
}

type VideoEventCallback = (event: VideoEvent) => void;

interface ThumbnailData {
    buffer: ArrayBuffer;
    width: number;
    height: number;
    time: number;
}

interface VideoMetadata {
    duration: number;
    width: number;
    height: number;
    rotation: number;
    format: string;
    videoCodec: string;
    audioCodec: string;
    bitrate: number;
    fps: number;
    // HDR 資訊
    isHdr: boolean;
    hdrPrimaries: string;
    hdrTransfer: string;
    hdrMaxLuminance: number;
    // 音頻資訊
    sampleRate: number;
    channels: number;
}

interface HdrInfo {
    /** Whether the video is HDR */
    isHdr: boolean;
    /** Color primaries (e.g., 'bt.709', 'bt.2020') */
    primaries: string;
    /** Transfer function (e.g., 'bt.1886', 'pq', 'hlg') */
    transfer: string;
    /** Peak luminance in nits */
    maxLuminance: number;
    /** Whether HDR output mode is currently enabled */
    hdrModeEnabled: boolean;
}

/**
 * Target resolution for frame rendering
 * If provided, frames will be downscaled to fit within these dimensions
 * while preserving aspect ratio
 */
interface TargetResolution {
    /** Target width in pixels (considering device pixel ratio) */
    width: number;
    /** Target height in pixels (considering device pixel ratio) */
    height: number;
}

/**
 * 幀元數據回調
 * 只在首幀或元數據變化時發送（減少 IPC 開銷）
 */
type FrameMetadataCallback = (data: {
    instanceId: string;
    metadata: FrameMetadata;
}) => void;

/**
 * 幀推送回調（輕量版）
 * 接收主進程主動推送的視頻幀（純 buffer，無包裝）
 */
type FramePushCallback = (buffer: ArrayBuffer) => void;

interface ElectronAPI {
    video: {
        // 實例管理
        createInstance: (instanceId: string, options?: { hwdec?: string }) => Promise<boolean>;
        destroyInstance: (instanceId: string) => Promise<void>;
        // 所有操作都需要 instanceId
        load: (instanceId: string, filePath: string) => Promise<boolean>;
        seek: (instanceId: string, position: number, mode?: string) => Promise<boolean>;
        play: (instanceId: string) => Promise<boolean>;
        pause: (instanceId: string) => Promise<boolean>;
        stop: (instanceId: string) => Promise<boolean>;
        togglePlay: (instanceId: string) => Promise<boolean>;
        getState: (instanceId: string) => Promise<VideoState | null>;
        getPosition: (instanceId: string) => Promise<number>;
        getDuration: (instanceId: string) => Promise<number>;
        setVolume: (instanceId: string, volume: number) => Promise<boolean>;
        setSpeed: (instanceId: string, speed: number) => Promise<boolean>;
        setMute: (instanceId: string, muted: boolean) => Promise<boolean>;
        getMute: (instanceId: string) => Promise<boolean>;
        setLoop: (instanceId: string, loop: boolean) => Promise<boolean>;
        /**
         * Get current video frame, optionally downscaled to target resolution
         * @param instanceId - The instance ID
         * @param targetResolution - If provided, frame will be downscaled to fit within these dimensions
         * @deprecated Use frame push mode instead (startFramePush/stopFramePush)
         */
        getFrame: (instanceId: string, targetResolution?: TargetResolution) => Promise<FrameData | null>;
        getFrameAt: (instanceId: string, time: number) => Promise<ThumbnailData | null>;
        requestScreenshot: (instanceId: string, time: number) => Promise<boolean>;
        getMetadata: (instanceId: string) => Promise<VideoMetadata | null>;
        getHdrInfo: (instanceId: string) => Promise<HdrInfo | null>;
        setHdrMode: (instanceId: string, enabled: boolean) => Promise<boolean>;
        destroy: () => Promise<void>;
        /**
         * 訂閱視頻事件
         * @param instanceId - 只接收此實例的事件，如果為 null 則接收所有事件
         * @param callback - 事件回調
         * @returns 取消訂閱函數
         */
        onEvent: (instanceId: string | null, callback: VideoEventCallback) => () => void;
        checkSupport: (filePath: string) => Promise<FileSupportResult>;

        // ===== 幀推送模式 API =====
        /**
         * 啟動幀推送模式
         * 主進程會主動推送視頻幀到渲染進程，減少 IPC 延遲
         * @param instanceId - 實例 ID
         * @param targetResolution - 目標解析度（用於 GPU 縮放）
         */
        startFramePush: (instanceId: string, targetResolution?: TargetResolution) => Promise<boolean>;

        /**
         * 停止幀推送模式
         * @param instanceId - 實例 ID
         */
        stopFramePush: (instanceId: string) => Promise<void>;

        /**
         * 更新幀推送的目標解析度
         * @param instanceId - 實例 ID
         * @param targetResolution - 新的目標解析度
         */
        updateFramePushResolution: (instanceId: string, targetResolution: TargetResolution) => Promise<void>;

        /**
         * 設置 scrubbing（拖拽預覽）模式
         * 啟用後 seek 會使用兩階段策略：先 keyframe 快速顯示，停頓後補精準幀
         * @param instanceId - 實例 ID
         * @param enabled - 是否啟用 scrubbing 模式
         */
        setScrubbing: (instanceId: string, enabled: boolean) => Promise<void>;

        /**
         * 訂閱幀元數據事件
         * 元數據只在首幀或變化時發送（減少 IPC 開銷）
         * @param instanceId - 只接收此實例的元數據，如果為 null 則接收所有實例
         * @param callback - 元數據回調
         * @returns 取消訂閱函數
         */
        onFrameMetadata: (instanceId: string | null, callback: FrameMetadataCallback) => () => void;

        /**
         * 訂閱幀推送事件（專屬通道，純 buffer）
         * @param instanceId - 實例 ID（用於訂閱專屬通道 video:framePush:${instanceId}）
         * @param callback - 幀推送回調（直接接收 ArrayBuffer）
         * @returns 取消訂閱函數
         */
        onFramePush: (instanceId: string, callback: FramePushCallback) => () => void;
    };
    dialog: {
        openFile: () => Promise<string | null>;
        openSubtitle: () => Promise<string | null>;
    };
    app: {
        getInfo: () => Promise<AppInfo>;
    };
}

// Expose APIs to renderer process
const electronAPI: ElectronAPI = {
    video: {
        // 實例管理
        createInstance: (instanceId: string, options?: { hwdec?: string }) => ipcRenderer.invoke('video:createInstance', instanceId, options),
        destroyInstance: (instanceId: string) => ipcRenderer.invoke('video:destroyInstance', instanceId),
        // 播放控制（帶 instanceId）
        load: (instanceId: string, filePath: string) => ipcRenderer.invoke('video:load', instanceId, filePath),
        seek: (instanceId: string, position: number, mode?: string) => ipcRenderer.invoke('video:seek', instanceId, position, mode),
        play: (instanceId: string) => ipcRenderer.invoke('video:play', instanceId),
        pause: (instanceId: string) => ipcRenderer.invoke('video:pause', instanceId),
        stop: (instanceId: string) => ipcRenderer.invoke('video:stop', instanceId),
        togglePlay: (instanceId: string) => ipcRenderer.invoke('video:togglePlay', instanceId),
        getState: (instanceId: string) => ipcRenderer.invoke('video:getState', instanceId),
        getPosition: (instanceId: string) => ipcRenderer.invoke('video:getPosition', instanceId),
        getDuration: (instanceId: string) => ipcRenderer.invoke('video:getDuration', instanceId),
        setVolume: (instanceId: string, volume: number) => ipcRenderer.invoke('video:setVolume', instanceId, volume),
        setSpeed: (instanceId: string, speed: number) => ipcRenderer.invoke('video:setSpeed', instanceId, speed),
        setMute: (instanceId: string, muted: boolean) => ipcRenderer.invoke('video:setMute', instanceId, muted),
        getMute: (instanceId: string) => ipcRenderer.invoke('video:getMute', instanceId),
        setLoop: (instanceId: string, loop: boolean) => ipcRenderer.invoke('video:setLoop', instanceId, loop),
        getFrame: (instanceId: string, targetResolution?: { width: number; height: number }) =>
            ipcRenderer.invoke('video:getFrame', instanceId, targetResolution),
        getFrameAt: (instanceId: string, time: number) => ipcRenderer.invoke('video:getFrameAt', instanceId, time),
        requestScreenshot: (instanceId: string, time: number) => ipcRenderer.invoke('video:requestScreenshot', instanceId, time),
        getMetadata: (instanceId: string) => ipcRenderer.invoke('video:getMetadata', instanceId),
        getHdrInfo: (instanceId: string) => ipcRenderer.invoke('video:getHdrInfo', instanceId),
        setHdrMode: (instanceId: string, enabled: boolean) => ipcRenderer.invoke('video:setHdrMode', instanceId, enabled),
        destroy: () => ipcRenderer.invoke('video:destroy'),
        onEvent: (instanceId: string | null, callback: VideoEventCallback) => {
            const handler = (_event: Electron.IpcRendererEvent, data: VideoEvent) => {
                // 如果指定了 instanceId，只處理該實例的事件
                if (instanceId === null || data.instanceId === instanceId) {
                    callback(data);
                }
            };
            ipcRenderer.on('video:event', handler);
            // Return unsubscribe function
            return () => {
                ipcRenderer.removeListener('video:event', handler);
            };
        },
        checkSupport: (filePath: string) => ipcRenderer.invoke('video:checkSupport', filePath),

        // ===== 幀推送模式實現 =====
        startFramePush: (instanceId: string, targetResolution?: { width: number; height: number }) =>
            ipcRenderer.invoke('video:startFramePush', instanceId, targetResolution),

        stopFramePush: (instanceId: string) =>
            ipcRenderer.invoke('video:stopFramePush', instanceId),

        updateFramePushResolution: (instanceId: string, targetResolution: { width: number; height: number }) =>
            ipcRenderer.invoke('video:updateFramePushResolution', instanceId, targetResolution),

        setScrubbing: (instanceId: string, enabled: boolean) =>
            ipcRenderer.invoke('video:setScrubbing', instanceId, enabled),

        onFrameMetadata: (instanceId: string | null, callback: (data: { instanceId: string; metadata: FrameMetadata }) => void) => {
            const handler = (_event: Electron.IpcRendererEvent, data: { instanceId: string; metadata: FrameMetadata }) => {
                // 如果指定了 instanceId，只處理該實例的元數據
                if (instanceId === null || data.instanceId === instanceId) {
                    callback(data);
                }
            };
            ipcRenderer.on('video:frameMetadata', handler);
            // Return unsubscribe function
            return () => {
                ipcRenderer.removeListener('video:frameMetadata', handler);
            };
        },

        onFramePush: (instanceId: string, callback: (buffer: ArrayBuffer) => void) => {
            const channel = `video:framePush:${instanceId}`;
            const handler = (_event: Electron.IpcRendererEvent, buffer: ArrayBuffer) => {
                callback(buffer);
            };
            ipcRenderer.on(channel, handler);
            // Return unsubscribe function
            return () => {
                ipcRenderer.removeListener(channel, handler);
            };
        },
    },
    dialog: {
        openFile: () => ipcRenderer.invoke('dialog:openFile'),
        openSubtitle: () => ipcRenderer.invoke('dialog:openSubtitle'),
    },
    app: {
        getInfo: () => ipcRenderer.invoke('app:getInfo'),
    },
};

contextBridge.exposeInMainWorld('electronAPI', electronAPI);

// Add type declaration for window
declare global {
    interface Window {
        electronAPI: ElectronAPI;
    }
}
